mapper.update:
UPDATE ${prefix}LOG_PARTITION
SET TERM = #{term}
WHERE PARTITION_ID = #{partitionId} AND TERM < #{term}

mapper.select:
SELECT LOW_POSITION, HIGH_POSITION, TERM, DATA
FROM ${prefix}LOG_BLOCK
WHERE PARTITION_ID = #{partitionId} AND LOW_POSITION <= #{position}
ORDER BY LOW_POSITION DESC
${keysetPaging.limit}

SELECT LOW_POSITION, HIGH_POSITION, TERM, DATA
FROM ${prefix}LOG_BLOCK
WHERE PARTITION_ID = #{partitionId} AND LOW_POSITION > #{lowPosition}
ORDER BY LOW_POSITION
${keysetPaging.limit}
